15	 */
16	public final class ApiDtos {
17	
18	    private ApiDtos() {
19	    }
20	
21	    /** 初始段落输入。 */
22	    public record SegmentInput(
23	            @NotBlank(message = "segmentId 不能为空") @Size(max = 64) String segmentId,
24	            @NotBlank(message = "sourceText 不能为空") String sourceText) {
