    List<DocumentRow> rows = jdbc.query(
            "SELECT document_id, target_languages, draft_version, published_version, term_version "
                    + "FROM document WHERE document_id = ?",
            DOCUMENT_MAPPER, documentId);
    return rows.stream().findFirst();
}

